using System;
using System.IO;
using System.Linq;
using PowerPointIntelligence.AddIn;
internal static class ProcessFlowTests
{
    private static int count;
    private static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL process flow "+name);count++;}
    private static void Reject(Action action,string name){try{action();}catch(Exception ex) when(ex is InvalidDataException||ex is InvalidOperationException){count++;return;}throw new Exception("FAIL expected process rejection "+name);}
    private static ProcessGridSpec Grid(int rows=2,int columns=3){var s=ProcessGridPlan.Create(42,rows,columns,960,540);int id=1;foreach(var c in s.Cells)c.ShapeId=id++;return s;}
    internal static void Run()
    {
        count=0;var grid=Grid();ProcessGridPlan.Validate(grid,960,540);Check(grid.Cells.Count==6,"default rectangular cells");Check(ProcessGridPlan.Kind(grid.Cells[0])=="rightPentagon"&&ProcessGridPlan.Kind(grid.Cells[1])=="chevron"&&ProcessGridPlan.Kind(grid.Cells[3])=="textbox","header and body kinds");
        foreach(var c in grid.Cells){var b=ProcessGridPlan.Bounds(grid,c);Check(b.Width>=48&&b.Height>=28&&b.Right<=960&&b.Bottom<=540,"native cells fit canvas");}
        var row=ProcessGridPlan.Change(grid,"add-row",0,1);Check(row.Rows==3&&row.Cells.Count==9&&row.Cells.Count(c=>c.ShapeId==0)==3&&row.Cells.Single(c=>c.ShapeId==4).Row==2,"add row shifts stable IDs and adds blank placeholders");Check(row.Height>grid.Height,"new row grows grid without shrinking text cells");Check(grid.Rows==2&&grid.Cells[3].Row==1,"source not mutated");
        var column=ProcessGridPlan.Change(grid,"add-column",0,0);Check(column.Columns==4&&column.Cells.Count==8&&column.Cells.Single(c=>c.ShapeId==2).Column==2,"add column shifts stable identities");
        var moved=ProcessGridPlan.Change(grid,"move-column",1,0,true);Check(moved.Cells.Single(c=>c.ShapeId==1).Column==1&&moved.Cells.Single(c=>c.ShapeId==2).Column==0&&moved.Cells.Single(c=>c.ShapeId==4).Column==1,"whole column reorder includes body");Check(ProcessGridPlan.Kind(moved.Cells.Single(c=>c.ShapeId==2))=="rightPentagon","new first header becomes pentagon");
        var deleted=ProcessGridPlan.Change(grid,"delete-row",0,0);Check(deleted.Rows==1&&deleted.Cells.Count(c=>c.Active)==3&&deleted.Cells.Count(c=>!c.Active)==3&&deleted.Cells.Where(c=>!c.Active).All(c=>c.Row==-1&&c.Column==-1),"removed row preserved as retired native cells");
        deleted=ProcessGridPlan.Change(grid,"delete-column",0,0);Check(deleted.Columns==2&&deleted.Cells.Count(c=>c.Active)==4&&deleted.Cells.Single(c=>c.ShapeId==2).Column==0,"removed column retains history and shifts surviving cells");
        string xml=ProcessGridCodec.Encode(deleted);var copy=ProcessGridCodec.Decode(xml);Check(copy.Cells.Count==6&&copy.Cells.Count(c=>!c.Active)==2,"retired identities persist");Check(ProcessGridCodec.Encode(copy)==xml,"deterministic strict XML");
        for(int r=0;r<20;r++)for(int c=0;c<12;c++){Check(ProcessGridPlan.Stripe("row",r,c,123,456)==(r%2==0?123:456),"row stripe parity");Check(ProcessGridPlan.Stripe("column",r,c,123,456)==(c%2==0?123:456),"column stripe parity");}
        Reject(()=>ProcessGridPlan.Stripe("diagonal",0,0,0,1),"unknown stripe axis");Reject(()=>ProcessGridPlan.Stripe("row",0,0,-1,1),"invalid color");
        Reject(()=>ProcessGridPlan.Change(Grid(1,1),"delete-row",0,0),"last row");Reject(()=>ProcessGridPlan.Change(Grid(1,1),"delete-column",0,0),"last column");Reject(()=>ProcessGridPlan.Change(grid,"move-column",0,0,false),"first column left");Reject(()=>ProcessGridPlan.Change(grid,"move-column",0,2,true),"last column right");Reject(()=>ProcessGridPlan.Change(grid,"erase-all",0,0),"unknown action");Reject(()=>ProcessGridPlan.Change(grid,"add-row",3,0),"unknown selection");Reject(()=>ProcessGridPlan.Create(42,21,3,960,3000),"row bound");Reject(()=>ProcessGridPlan.Create(42,2,13,960,540),"column bound");Reject(()=>ProcessGridPlan.Create(42,20,3,960,540),"physical overflow");
        var large=ProcessGridPlan.Create(42,20,12,2000,3000);int id=1;foreach(var c in large.Cells)c.ShapeId=id++;ProcessGridPlan.Validate(large,2000,3000);Check(large.Cells.Count==240,"maximum native rectangular size");Reject(()=>ProcessGridPlan.Change(large,"add-row",0,0),"maximum rows");Reject(()=>ProcessGridPlan.Change(large,"add-column",0,0),"maximum columns");
        var bad=Grid();bad.Cells.RemoveAt(0);Reject(()=>ProcessGridPlan.Validate(bad,960,540),"missing cell");bad=Grid();bad.Cells[1].ShapeId=bad.Cells[0].ShapeId;Reject(()=>ProcessGridPlan.Validate(bad,960,540),"duplicate identity");bad=Grid();bad.Cells[1].Column=0;Reject(()=>ProcessGridPlan.Validate(bad,960,540),"duplicate coordinate");bad=Grid();bad.Cells[0].ShapeId=0;Reject(()=>ProcessGridCodec.Encode(bad),"unassigned persistent identity");bad=Grid();bad.Left=Single.NaN;Reject(()=>ProcessGridPlan.Validate(bad,960,540),"nonfinite geometry");bad=Grid();bad.Left=900;Reject(()=>ProcessGridPlan.Validate(bad,960,540),"offslide grid");
        xml=ProcessGridCodec.Encode(grid);Reject(()=>ProcessGridCodec.Decode(xml.Replace("version=\"1\"","version=\"2\"")),"schema");Reject(()=>ProcessGridCodec.Decode(xml.Replace("grid:v1","grid:v2")),"namespace");Reject(()=>ProcessGridCodec.Decode(xml.Replace("rows=\"2\"","rows=\"21\"")),"invalid persisted size");Reject(()=>ProcessGridCodec.Decode(xml.Replace("active=\"true\"","active=\"yes\"")),"boolean");Reject(()=>ProcessGridCodec.Decode(xml.Replace("<cell ","<cell extra=\"x\" ")),"unknown field");Reject(()=>ProcessGridCodec.Decode(xml.Replace("</grid>","<foreign /></grid>")),"unknown element");Reject(()=>ProcessGridCodec.Decode("<!DOCTYPE grid [<!ENTITY a 'x'>]>"+xml),"DTD");Reject(()=>ProcessGridCodec.Decode("<!DOCTYPE grid SYSTEM 'file:///never-read'>"+xml),"external entity");Reject(()=>ProcessGridCodec.Decode("<!--unexpected-->"+xml),"comment");Reject(()=>ProcessGridCodec.Decode(xml.Substring(1)),"malformed XML");Reject(()=>ProcessGridCodec.Decode(new string('x',150001)),"XML size bound");
        var resized=ProcessGridPlan.Resize(grid,80,80,700,200,960,540);Check(resized.Left==80&&resized.Top==80&&resized.Width==700&&grid.Left==40&&resized.Cells[0].ShapeId==grid.Cells[0].ShapeId,"resize preserves identities and source geometry");Reject(()=>ProcessGridPlan.Resize(grid,900,80,700,200,960,540),"resize offslide");Reject(()=>ProcessGridPlan.Resize(grid,80,80,100,50,960,540),"resize unreadable cells");
        Console.WriteLine("Process flow tests passed: "+count);
    }
}

